import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { User, Mail, Phone, Lock, ArrowLeft, Droplet, ShieldCheck, KeyRound } from 'lucide-react';

export default function RegisterPage() {
  const [step, setStep] = useState(1); // Step 1: Form, Step 2: OTP Verification
  const [registerMethod, setRegisterMethod] = useState('email');
  const [bloodGroup, setBloodGroup] = useState('O+');
  const [otp, setOtp] = useState(['', '', '', '']);

  const bloodGroups = ['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'];

  const handleOtpChange = (value, index) => {
    if (isNaN(value)) return;
    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);

    // Auto focus next input
    if (value && index < 3) {
      const nextInput = document.getElementById(`otp-input-${index + 1}`);
      if (nextInput) nextInput.focus();
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-rose-50 via-white to-slate-100 flex items-center justify-center p-4 relative overflow-hidden">
      
      {/* Background Orbs */}
      <div className="absolute -top-20 -right-20 w-80 h-80 bg-brand-500/10 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute -bottom-20 -left-20 w-72 h-72 bg-rose-200/50 rounded-full blur-3xl pointer-events-none" />

      <motion.div 
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.4 }}
        className="w-full max-w-lg bg-white/90 backdrop-blur-xl p-8 rounded-3xl shadow-2xl border border-rose-100/60 relative z-10 space-y-6"
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-slate-100 pb-4">
          <Link to="/" className="inline-flex items-center gap-1.5 text-xs font-bold text-slate-500 hover:text-brand-600 transition">
            <ArrowLeft className="w-4 h-4" /> হোমে ফিরুন
          </Link>
          <div className="flex items-center gap-1.5">
            <div className="w-6 h-6 rounded-full bg-brand-600 flex items-center justify-center text-white font-bold text-xs">
              🩸
            </div>
            <span className="font-black text-slate-900 text-sm">BloodHero</span>
          </div>
        </div>

        <AnimatePresence mode="wait">
          {step === 1 ? (
            /* --- STEP 1: REGISTRATION FORM --- */
            <motion.div
              key="step1"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
              className="space-y-5"
            >
              <div className="text-center space-y-1">
                <h2 className="text-2xl font-black text-slate-900">নতুন অ্যাকাউন্ট তৈরি করুন</h2>
                <p className="text-slate-500 text-xs font-medium">রক্তদাতা ও গ্রহীতা কমিউনিটিতে যুক্ত হতে তথ্য দিন</p>
              </div>

              {/* Toggle Pills */}
              <div className="flex bg-slate-100 p-1 rounded-2xl text-xs font-bold">
                <button
                  type="button"
                  onClick={() => setRegisterMethod('email')}
                  className={`flex-1 py-2 rounded-xl transition-all ${
                    registerMethod === 'email' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500'
                  }`}
                >
                  ইমেইল দিয়ে
                </button>
                <button
                  type="button"
                  onClick={() => setRegisterMethod('phone')}
                  className={`flex-1 py-2 rounded-xl transition-all ${
                    registerMethod === 'phone' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500'
                  }`}
                >
                  ফোন নম্বর দিয়ে
                </button>
              </div>

              <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); setStep(2); }}>
                {/* Full Name */}
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">পূর্ণ নাম</label>
                  <div className="relative">
                    <User className="w-4 h-4 absolute left-3.5 top-3.5 text-slate-400" />
                    <input 
                      type="text" 
                      required
                      placeholder="আপনার নাম লিখুন"
                      className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 focus:outline-none focus:border-brand-600 text-xs font-medium bg-white"
                    />
                  </div>
                </div>

                {/* Email / Phone */}
                {registerMethod === 'email' ? (
                  <div>
                    <label className="block text-xs font-bold text-slate-700 mb-1">ইমেইল ঠিকানা</label>
                    <div className="relative">
                      <Mail className="w-4 h-4 absolute left-3.5 top-3.5 text-slate-400" />
                      <input 
                        type="email" 
                        required
                        placeholder="example@mail.com"
                        className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 focus:outline-none focus:border-brand-600 text-xs font-medium bg-white"
                      />
                    </div>
                  </div>
                ) : (
                  <div>
                    <label className="block text-xs font-bold text-slate-700 mb-1">ফোন নম্বর</label>
                    <div className="relative">
                      <Phone className="w-4 h-4 absolute left-3.5 top-3.5 text-slate-400" />
                      <input 
                        type="tel" 
                        required
                        placeholder="01700000000"
                        className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 focus:outline-none focus:border-brand-600 text-xs font-medium bg-white"
                      />
                    </div>
                  </div>
                )}

                {/* Blood Group Selector */}
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1.5">রক্তের গ্রুপ নির্বাচন করুন</label>
                  <div className="grid grid-cols-4 gap-2">
                    {bloodGroups.map((bg) => (
                      <button
                        key={bg}
                        type="button"
                        onClick={() => setBloodGroup(bg)}
                        className={`py-2 rounded-xl text-xs font-bold border transition ${
                          bloodGroup === bg 
                            ? 'bg-brand-600 text-white border-brand-600 shadow-md shadow-brand-600/20' 
                            : 'bg-slate-50 text-slate-700 border-slate-200 hover:border-slate-300'
                        }`}
                      >
                        {bg}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Password */}
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">পাসওয়ার্ড</label>
                  <div className="relative">
                    <Lock className="w-4 h-4 absolute left-3.5 top-3.5 text-slate-400" />
                    <input 
                      type="password" 
                      required
                      placeholder="••••••••"
                      className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 focus:outline-none focus:border-brand-600 text-xs font-medium bg-white"
                    />
                  </div>
                </div>

                <button
                  type="submit"
                  className="w-full bg-brand-600 hover:bg-brand-700 text-white font-bold text-xs py-3.5 rounded-xl shadow-lg shadow-brand-600/30 transition transform active:scale-95"
                >
                  ওটিপি পাঠান (Next)
                </button>
              </form>
            </motion.div>
          ) : (
            /* --- STEP 2: OTP VERIFICATION --- */
            <motion.div
              key="step2"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              className="space-y-6 text-center"
            >
              <div className="w-14 h-14 bg-rose-100 text-brand-600 rounded-full flex items-center justify-center mx-auto shadow-inner">
                <KeyRound className="w-7 h-7" />
              </div>

              <div className="space-y-1">
                <h2 className="text-2xl font-black text-slate-900">OTP যাচাইকরণ</h2>
                <p className="text-slate-500 text-xs font-medium">
                  আপনার {registerMethod === 'email' ? 'ইমেইলে' : 'ফোনে'} ৪-সংখ্যার একটি কোড পাঠানো হয়েছে।
                </p>
              </div>

              {/* 4 Digit OTP Inputs */}
              <div className="flex justify-center gap-3 py-2">
                {otp.map((digit, idx) => (
                  <input
                    key={idx}
                    id={`otp-input-${idx}`}
                    type="text"
                    maxLength="1"
                    value={digit}
                    onChange={(e) => handleOtpChange(e.target.value, idx)}
                    className="w-12 h-14 text-center text-xl font-black rounded-2xl border-2 border-slate-200 focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-600/20 bg-white"
                  />
                ))}
              </div>

              <div className="space-y-3">
                <button
                  type="button"
                  onClick={() => alert("অ্যাকাউন্ট সফলভাবে তৈরি হয়েছে!")}
                  className="w-full bg-brand-600 hover:bg-brand-700 text-white font-bold text-xs py-3.5 rounded-xl shadow-lg shadow-brand-600/30 transition transform active:scale-95"
                >
                  যাচাই করুন ও সাইন আপ শেষ করুন
                </button>

                <button
                  type="button"
                  onClick={() => setStep(1)}
                  className="text-xs font-bold text-slate-400 hover:text-slate-600 transition"
                >
                  তথ্য পরিবর্তন করুন
                </button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Footer Link */}
        <div className="text-center pt-2">
          <p className="text-xs text-slate-500 font-medium">
            আগে থেকেই অ্যাকাউন্ট আছে?{' '}
            <Link to="/login" className="font-bold text-brand-600 hover:underline">
              লগইন করুন
            </Link>
          </p>
        </div>
      </motion.div>
    </div>
  );
}
